package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The people's plans on a sheet. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class PlanController {

    /** A plan as the screen shows it: the amount with two decimals, dates YYYY-MM-DD, every so many days or
     *  the day of the month (the other null), how many claims it has made so far, and its next dates: the first
     *  five plan dates after the sheet's today and on or before its end. */
    public record PlanView(long id, long personId, String amount, String start, Integer every, Integer day,
            String end, int generated, List<String> nextDates) {

        static PlanView of(Plan p, LocalDate today) {
            return new PlanView(p.getId(), p.getPersonId(), p.getAmount().toPlainString(), p.getStart().toString(),
                    p.getEvery(), p.getDay(), p.getEnd().toString(), p.getGeneratedCount(),
                    p.nextDates(today, 5).stream().map(LocalDate::toString).toList());
        }
    }

    public record PlanRequest(
            @NotNull @Digits(integer = 13, fraction = 2) BigDecimal amount,
            @NotNull LocalDate start,
            Integer every,
            Integer day,
            @NotNull LocalDate end) {
    }

    /** How many a generate made, the claims it made in the order made, and the sheet's plans. */
    public record GenerateView(int made, List<ClaimView> claims, List<PlanView> plans) {
    }

    private final PlanService service;

    public PlanController(PlanService service) {
        this.service = service;
    }

    /** The sheet's plans, in the order they were added. */
    @GetMapping("/plans")
    public List<PlanView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        String sid = sheetId.trim();
        List<Plan> plans = service.list(sid);
        LocalDate today = service.today(sid);
        return plans.stream().map(p -> PlanView.of(p, today)).toList();
    }

    /** Add a plan to a person. */
    @PostMapping("/people/{personId}/plans")
    public PlanView add(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PlanRequest request) {
        String sid = sheetId.trim();
        Plan plan = service.add(sid, user.trim(), personId, request.amount(), request.start(), request.every(),
                request.day(), request.end());
        return PlanView.of(plan, service.today(sid));
    }

    /** Make the plans' claims due by the sheet's today. */
    @PostMapping("/plans/generate")
    public GenerateView generate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        PlanService.Generated done = service.generate(sheetId.trim(), user.trim());
        return new GenerateView(done.claims().size(), done.claims().stream().map(ClaimView::of).toList(),
                done.plans().stream().map(p -> PlanView.of(p, done.today())).toList());
    }

    /** A plan that cannot be added is refused with the reason, for the screen to show. */
    @ExceptionHandler(PlanRefusedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> refused(PlanRefusedException e) {
        return Map.of("message", e.getMessage());
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person's plan: a DRAFT claim of its amount on every plan date up to its end — the start then every so
 *  many days, or monthly on a day of the month — and the plan dates it has made a claim for so far. */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private long personId;

    @Column(name = "amount", nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    /** Every so many days; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) of a monthly plan; null for one run every so many days. */
    @Column(name = "month_day")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_generated", joinColumns = @JoinColumn(name = "plan_id"))
    @Column(name = "on_date")
    private Set<LocalDate> generated = new HashSet<>();

    protected Plan() {
    }

    public Plan(String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    /** How many claims the plan has made so far. */
    public int getGeneratedCount() {
        return generated.size();
    }

    /** The plan dates up to its end and the given day that it has made no claim for yet, earliest first. */
    public List<LocalDate> datesDue(LocalDate today) {
        LocalDate last = end.isBefore(today) ? end : today;
        return dates(start, last, Integer.MAX_VALUE).stream().filter(d -> !generated.contains(d)).toList();
    }

    /** The first so many plan dates after the given day and on or before its end, earliest first, whether or
     *  not it has made a claim for them. */
    public List<LocalDate> nextDates(LocalDate today, int count) {
        return dates(today.plusDays(1), end, count);
    }

    /** The plan dates from the given first to last day, earliest first, at most so many. A monthly plan's dates
     *  are its day in every month from the start's month, a day beyond the month's length falling on its last
     *  day, dates before the start left out. */
    private List<LocalDate> dates(LocalDate first, LocalDate last, int max) {
        List<LocalDate> out = new ArrayList<>();
        if (day != null) {
            for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last) && out.size() < max;
                    m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isBefore(first) && !d.isAfter(last)) {
                    out.add(d);
                }
            }
            return out;
        }
        LocalDate d = start;
        if (d.isBefore(first)) {
            long steps = (ChronoUnit.DAYS.between(start, first) + every - 1) / every;
            d = start.plusDays(steps * every);
        }
        for (; !d.isAfter(last) && out.size() < max; d = d.plusDays(every)) {
            out.add(d);
        }
        return out;
    }

    /** Keep that the plan has made its claim for the plan date. */
    public void generated(LocalDate date) {
        generated.add(date);
    }
}
